for category, rows in DATA.items():
    DATA[category]=[(*row[:4],CONTROLS[category].get(i)) for i,row in enumerate(rows,1)]

def question(category, lang):
    policy,criteria=POL[category][lang]
    return {'decision': {'type':'choice','instructions':(G_DE if lang=='de' else G_EN)+policy,'criteria':criteria}}

def write_jsonl(filename, values):
    (D/filename).write_text(''.join(json.dumps(x,ensure_ascii=False,separators=(',',':'))+'\n' for x in values),encoding='utf-8')

main=[]; diagnostic=[]; pairs=[]
for cat, rows in DATA.items():
    assert len(rows)==20,(cat,len(rows))
    assert sum(row[4] is not None for row in rows)==5,cat
    counts=collections.Counter(row[0] for row in rows)
    assert set(counts)==set(POL[cat]['de'][1]) and len(set(counts.values()))==1,(cat,counts)
    assert list(POL[cat]['de'][1])==list(POL[cat]['en'][1])
    for i,(label,de,tags,rationale,en) in enumerate(rows,1):
        stem=f'{cat}_{i:03d}'; pair_id=f'pair_{stem}' if en else None
        base={'category':cat,'expected':{'decision':label},'tags':tags.split(','),'pair_id':pair_id,'gold_rationale':rationale}
        main.append(dict(base,id=f'de_{stem}',language='de',schema_language='de',split='german_primary',input=de,questions=question(cat,'de')))
        if en:
            en_id=f'en_{stem}'; mix_id=f'de_en_schema_{stem}'
            main.append(dict(base,id=en_id,language='en',schema_language='en',split='english_control',input=en,questions=question(cat,'en')))
            diagnostic.append(dict(base,id=mix_id,language='de',schema_language='en',split='mixed_schema_diagnostic',input=de,questions=question(cat,'en')))
            pairs.append({'pair_id':pair_id,'category':cat,'german_id':f'de_{stem}','english_id':en_id,'mixed_id':mix_id})
write_jsonl('cases.jsonl',main)
write_jsonl('diagnostic_cases.jsonl',diagnostic)
write_jsonl('pairs.jsonl',pairs)
allcases=main+diagnostic
random.Random(20261002).shuffle(allcases)
# An allowlist, NOT deletion of a few metadata fields: only these two fields reach the decision encoder.
requests=[{'id':c['id'],'request':{'model':'clef-flash','state':c['input'],'questions':c['questions']}} for c in allcases]
write_jsonl('requests.jsonl',requests)
write_jsonl('gold.jsonl',[{k:c[k] for k in ('id','category','language','schema_language','split','expected','tags','pair_id','gold_rationale')} for c in allcases])
(D/'policies.json').write_text(json.dumps({cat:{lang:question(cat,lang) for lang in ('de','en')} for cat in POL},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
summary={'primary_german':120,'english_controls':30,'mixed_schema_diagnostic':30,'total_requests':180,'random_order_seed':20261002,'categories':{cat:dict(collections.Counter(row[0] for row in rows)) for cat,rows in DATA.items()},'german_tag_counts':dict(collections.Counter(tag for rows in DATA.values() for row in rows for tag in row[2].split(','))),'english_pair_selection':'5 deliberately selected cases per category; covers every class plus spelling, idiom, injection, negation, distractors and self-correction; additional none/unsupported control in four-class categories'}
(D/'design_summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps(summary,ensure_ascii=False,indent=2))
